#!/usr/bin/env python3\n\"\"\"\nROM Manifest Generator\nInventory ROMs (.sfc/.smc and in ZIPs) with metadata: title, hash, size, region, mode.\nOutput: roms_manifest.json next to ROM_SOURCE/\n\"\"\"\n\nimport json\nimport os\nimport zipfile\nimport hashlib\nfrom pathlib import Path\n\nROM_SOURCE = Path(\"ROM_SOURCE\")\nOUTPUT_MANIFEST = ROM_SOURCE.parent / \"roms_manifest.json\"\n\nentries = []\n\nfor item in ROM_SOURCE.rglob('*'):  # Recursive scan including unzipped/\n    if item.is_file() and item.suffix in {'.sfc', '.smc'}:\n        entries.append(_process_rom(item))\n    elif item.suffix == '.zip':\n        with zipfile.ZipFile(item) as zf:\n            for zip_item in zf.namelist():\n                if Path(zip_item).suffix in {'.sfc', '.smc'}:\n                    with zf.open(zip_item) as rom_file:\n                        rom_data = rom_file.read()\n                        rom_path = item.name + '/' + zip_item  # Provenance\n                        entries.append(_process_rom_data(rom_data, rom_path))\n\nwith open(OUTPUT_MANIFEST, 'w') as f:\n    json.dump({\"roms\": entries}, f, indent=2)\n\nprint(f\"Generated manifest with {len(entries)} ROMs\")\n\ndef _process_rom(rom_path: Path):\n    with open(rom_path, 'rb') as f:\n        data = f.read()\n    return _process_rom_data(data, str(rom_path.name))\n\ndef _process_rom_data(data: bytes, provenance: str):\n    # Extract title from header (0x7FC0-0x7FDF for LoROM)\n    title = data[0x7FC0:0x7FD0].decode('ascii', errors='ignore').strip('\\x00')\n    if not title:\n        title = Path(provenance).stem.replace('.sfc', '').replace('.smc', '')  # Fallback\n\n    rom_hash = hashlib.sha256(data).hexdigest()\n    size = len(data)\n\n    # Region: Infer from path or header (e.g., USA if 'USA' in path)\n    region = 'USA' if 'USA' in provenance.upper() else 'Unknown'\n\n    # Mode: LoROM/HiROM from header byte 0x7FFE\n    map_mode = data[0x7FFE]\n    mode = 'LoROM' if map_mode == 0x30 else 'HiROM' if map_mode == 0x31 else 'Unknown'\n\n    return {\n        'provenance': provenance,\n        'title': title,\n        'hash': rom_hash,\n        'size': size,\n        'region': region,\n        'map_mode': mode\n    }\n
